import{_ as a,o as r,c as e,a2 as l}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"🛠️ 工具箱","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"features/tools.md","filePath":"features/tools.md"}'),o={name:"features/tools.md"};function d(i,t,h,n,s,c){return r(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="🛠️-工具箱" tabindex="-1">🛠️ 工具箱 <a class="header-anchor" href="#🛠️-工具箱" aria-label="Permalink to &quot;🛠️ 工具箱&quot;">​</a></h1><p>工具箱汇集了 EmuTrain 中的各类实用辅助功能，满足铁路爱好者的多样需求。</p><hr><h2 id="车站大屏" tabindex="-1">车站大屏 <a class="header-anchor" href="#车站大屏" aria-label="Permalink to &quot;车站大屏&quot;">​</a></h2><p>模拟查看全国各大车站的<strong>实时出发 / 到达信息大屏</strong>。</p><ul><li>进入后选择目标车站</li><li>显示该站近期的列车时刻与轨道信息</li><li>界面类似车站现场的候车大屏</li></ul><blockquote><p>⚠️ 数据仅供参考，以实际车站大屏为准<br> 数据来源：<a href="https://rail.moefactory.com/api/station/getBigScreenInfo" target="_blank" rel="noreferrer">rail.moefactory.com</a></p></blockquote><hr><h2 id="线路制造处" tabindex="-1">线路制造处 <a class="header-anchor" href="#线路制造处" aria-label="Permalink to &quot;线路制造处&quot;">​</a></h2><p>自定义创建和管理您的专属线路图。</p><h3 id="主要功能" tabindex="-1">主要功能 <a class="header-anchor" href="#主要功能" aria-label="Permalink to &quot;主要功能&quot;">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td>新建线路</td><td>自定义名称、添加站点、设置线路颜色</td></tr><tr><td>编辑线路</td><td>修改已有线路的站点与顺序</td></tr><tr><td>浏览线路</td><td>以列表形式管理所有保存的线路</td></tr><tr><td>搜索线路</td><td>在已保存线路中搜索</td></tr><tr><td>导入 JSON</td><td>从 JSON 文件导入线路数据</td></tr><tr><td>批量操作</td><td>批量选择并删除线路</td></tr></tbody></table><h3 id="线路商店" tabindex="-1">线路商店 <a class="header-anchor" href="#线路商店" aria-label="Permalink to &quot;线路商店&quot;">​</a></h3><p>线路商店提供由社区共享的线路文件，可以一键下载并导入到本地使用，方便快速获取热门线路的站点数据。</p><hr><h2 id="gps-速度计" tabindex="-1">GPS 速度计 <a class="header-anchor" href="#gps-速度计" aria-label="Permalink to &quot;GPS 速度计&quot;">​</a></h2><p>利用设备 GPS 实时测量当前行进速度，适合在乘车途中感受速度变化。</p><ul><li>显示实时<strong>GPS 测速</strong>（km/h）</li><li>适合铁路爱好者在高铁 / 动车上记录速度峰值</li></ul><div class="warning custom-block"><p class="custom-block-title">实验性功能</p><p>GPS 速度计为实验性功能，数据精度受 GPS 信号质量影响，可能不准，仅供娱乐参考，请勿用于安全相关判断。</p></div><hr><h2 id="动车图鉴" tabindex="-1">动车图鉴 <a class="header-anchor" href="#动车图鉴" aria-label="Permalink to &quot;动车图鉴&quot;">​</a></h2><p>精选了一批<strong>特殊涂装、节日彩绘、限定涂装</strong>等稀有列车的图片，共铁路爱好者欣赏与收藏。</p><ul><li>覆盖 CRH、CR 等各系列动车组</li><li>包含节日/纪念涂装、广告涂装等特殊车辆</li><li>支持浏览完整图鉴列表</li></ul><p>完整图鉴来源：<a href="https://china-emu.cn/Trains/ALL/" target="_blank" rel="noreferrer">china-emu.cn/Trains/ALL</a></p><hr><h2 id="关于软件" tabindex="-1">关于软件 <a class="header-anchor" href="#关于软件" aria-label="Permalink to &quot;关于软件&quot;">​</a></h2><p>展示 EmuTrain 的相关信息，包括：</p><ul><li>软件版本号与 Build 号</li><li>更新日志与新版本检测</li><li>数据来源列表</li><li>版权声明</li><li>开发者联系方式</li></ul><hr><h2 id="友情链接" tabindex="-1">友情链接 <a class="header-anchor" href="#友情链接" aria-label="Permalink to &quot;友情链接&quot;">​</a></h2><p>EmuTrain 推荐的相关应用与网站：</p><table tabindex="0"><thead><tr><th>应用 / 网站</th><th>简介</th><th>链接</th></tr></thead><tbody><tr><td>路路通</td><td>国铁综合出行 APP</td><td><a href="https://sj.qq.com/appdetail/com.lltskb.lltskb" target="_blank" rel="noreferrer">sj.qq.com</a></td></tr><tr><td>Rail.re 动车组查询</td><td>动车组交路查询网站</td><td><a href="https://rail.re/" target="_blank" rel="noreferrer">rail.re</a></td></tr><tr><td>RailGo</td><td>铁路信息查询 APP</td><td><a href="https://railgo.dev/android.html" target="_blank" rel="noreferrer">railgo.dev</a></td></tr><tr><td>MoeFactory 车箱</td><td>铁路综合数据平台</td><td><a href="https://sharyou.moefactory.com/" target="_blank" rel="noreferrer">sharyou.moefactory.com</a></td></tr><tr><td>动车组图鉴</td><td>全国动车组图片数据库</td><td><a href="https://china-emu.cn/" target="_blank" rel="noreferrer">china-emu.cn</a></td></tr></tbody></table>',32)])])}const b=a(o,[["render",d]]);export{p as __pageData,b as default};
